public class Methods {
    /** Returns value limited to [low, high], inclusive. Requires low <= high. No side effects. */
    static int clamp(int value, int low, int high) {
        if (low > high) throw new IllegalArgumentException("low > high");
        return Math.max(low, Math.min(value, high));
    }

    static void zeroFirst(int[] s) { s[0] = 0; }          // modifies the shared object.
    static void replace(int[] s) { s = new int[]{9, 9}; }   // reassigns the local copy only.

    public static void main(String[] args) {
        System.out.println(clamp(15, 0, 10));   // 10
        System.out.println(clamp(0, 0, 10));    // 0  (boundary)
        int[] scores = {5, 6, 7};
        zeroFirst(scores);                      // scores is now {0, 6, 7}.
        replace(scores);                        // scores still {0, 6, 7}.
        System.out.println(java.util.Arrays.toString(scores));
    }
}
